"""Writes experiments/EXP/REPORT_A1.md (EXP in E1, E6, E7, E8) from the A1 summaries produced by
experiments/common/amend_A1.py. Every number below is read from those JSON files; nothing is typed by hand.
Usage: uv run python experiments/common/write_A1_reports.py
"""
import json, os
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(os.path.dirname(HERE))
ALL = json.load(open(os.path.join(HERE, "A1_summary.json")))
HEAD = ("# {exp} — Amendment A1 (POST HOC, not preregistered): re-scoring\n\n"
        "Generated by `experiments/common/write_A1_reports.py` from `experiments/{exp}/analysis/A1_summary.json` and "
        "`A1_per_run.csv` (made by `experiments/common/amend_A1.py`). The reason and timing are in AMENDMENTS.md. "
        "The preregistered REPORT.md is unchanged and stays the primary record. Nothing here replaces it.\n\n")
COUNTS = [("thr_20", "thr_20 (registered: A_j >= 20% max A)"), ("thr_10", "thr_10 (registered headline)"),
          ("K_2pct", "K_2pct (post hoc: energy share >= 2%)"), ("K_5pct", "K_5pct (post hoc: energy share >= 5%)"),
          ("N_05", "N_05 (post hoc: fewest freqs with 95% of clean energy)"), ("N_10", "N_10 (post hoc: 90%)")]


def f(x, nd=3):
    return "nan" if x is None or (isinstance(x, float) and not np.isfinite(x)) else f"{x:.{nd}f}"


def ci(c):
    return f"[{f(c[0], 2)}, {f(c[1], 2)}]"


def count_table(g):
    out = ["| count definition | n | exact | within ±1 [95% CI over seeds] | R² identity | R² fitted | Spearman | OLS slope | mean signed error |",
           "|---|---|---|---|---|---|---|---|---|"]
    for k, lab in COUNTS:
        c = g[f"count_{k}_vs_Kstar"]
        out.append(f"| {lab} | {c['n']} | {f(c['frac_exact'], 2)} | {f(c['frac_within_tol'], 2)} {ci(c['frac_within_tol_boot_ci_over_seeds'])} | "
                   f"{f(c['r2_identity'], 2)} | {f(c['r2_linear_fit'], 2)} | {f(c['spearman'], 2)} | {f(c['linfit_meas_on_pred']['slope'], 2)} | {f(c['mean_signed_error'], 2)} |")
    return "\n".join(out) + "\n"


def null_stats(exp):
    N = json.load(open(os.path.join(ROOT, "experiments", exp, "analysis", "A1_summary.json")))["nulls_and_positive"]
    g = lambda k: [v[k] for v in N.values() if v.get(k) is not None]
    med = lambda L: float(np.median(L)) if L else None
    return {"ra_eff": med(g("random_allocation_median")), "ri_eff": med(g("random_init_net")),
            "pos_min": min(g("positive_control")) if g("positive_control") else None,
            "ra_tv": med(g("eps0.01_random_allocation_median_tv_min")), "ri_tv": med(g("eps0.01_random_init_net_tv_min")),
            "n_cells": len(N)}


def share_block(exp, g):
    e, n = g["efficiency"], null_stats(exp)
    L = ["**Programme efficiency** eff = value of the programme at the measured allocation / Gamma_s(p). It is 1 at any optimal "
         "allocation, whichever near-tied optimum or dilate the network lands on.\n",
         f"- trained ({g['n']} runs): median **{f(e['median'])}** [95% CI over seeds {f(e['median_ci_over_seeds'][0])}, {f(e['median_ci_over_seeds'][1])}], "
         f"10th–90th pct {f(e['q10'])}–{f(e['q90'])}; fraction >= 0.99: {f(e['frac_ge_0.99'], 2)}, >= 0.95: {f(e['frac_ge_0.95'], 2)}, >= 0.90: {f(e['frac_ge_0.90'], 2)}.",
         f"- nulls (median over {n['n_cells']} cells): random allocation on K* frequencies {f(n['ra_eff'])}; random-init network {f(n['ri_eff'])}. "
         f"Positive control (nu-block at y*): min {f(n['pos_min'], 6)}."]
    if "eps0.01" in g:
        q = g["eps0.01"]
        L += ["", "**Share match to the 1%-optimal vertex set** (vertex-cache primes p <= 37 only; V = every vertex, with all its dilates, "
              "whose programme value is within 1% of the optimum):\n",
              f"- trained ({q['n_cached']} runs): median min-TV **{f(q['median_tv_min'])}**; TV at the best-cosine vertex {f(q['median_tv_at_best_cos'])}; "
              f"cosine {f(q['median_cos_best'])}. The registered TV to y* on the same runs: {f(q['median_tv_to_ystar_registered_same_runs'])}.",
              f"- nulls: random allocation {f(n['ra_tv'])}; random-init network {f(n['ri_tv'])}.",
              f"- K_2pct inside the [K_min, K_max] of the 1% set: {f(q['frac_K2_in_eps_range'], 2)}."]
    return "\n".join(L) + "\n"


def cell_table(g, cached):
    cols = "| nu | p | s | K* | runner-up gap | n | median K_2pct | median N_05 | median thr_10 | median eff | min eff |" + (" 1%-set orbits | 1%-set K range | median min-TV (1%) |" if cached else "")
    out = [cols, "|" + "---|" * (cols.count("|") - 1)]
    for c in g["cells"]:
        row = (f"| {c['nu']} | {c['p']} | {c['s']} | {c['K_star']} | {f(c['runner_up_rel_gap'], 4) if c['runner_up_rel_gap'] is not None else '-'} | {c['n']} | "
               f"{c['median_K_2pct']} | {c['median_N_05']} | {c['median_thr_10']} | {f(c['median_eff'])} | {f(c['min_eff'])} |")
        if cached:
            row += (f" {c.get('eps0.01_n_orbits', '-')} | {c.get('eps0.01_K_range', '-')} | {f(c.get('eps0.01_median_tv_min'))} |" if "eps0.01_K_range" in c else " - | - | - |")
        out.append(row)
    return "\n".join(out) + "\n"


def write(exp, extra=""):
    S = ALL[exp]
    txt = HEAD.format(exp=exp)
    for grp, title in (("ok", "Converged runs (primary)"), ("not_converged", "Not-converged runs (margin > 0), reported separately")):
        g = S.get(grp)
        if not g:
            continue
        txt += f"## {title}\n\n### Counts vs K*\n\n" + count_table(g) + "\n### Shares\n\n" + share_block(exp, g)
        txt += "\n### Per cell\n\n" + cell_table(g, any("eps0.01_K_range" in c for c in g["cells"])) + "\n"
    txt += extra
    open(os.path.join(ROOT, "experiments", exp, "REPORT_A1.md"), "w").write(txt)


def e1b():
    B = ALL["E1b"]
    L = ["## E1b under A1 (same s, different nu)\n",
         f"Mean |difference of median K_2pct| between different nu at the same (p, s): **{f(B['mean_abs_dK2_same_s_across_nu'], 2)}** over {B['n_same_s_pairs']} pairs "
         f"({f(B['frac_same_s_pairs_within_1'], 2)} of pairs within 1). For scale, between different s at the same (p, nu): {f(B['mean_abs_dK2_same_nu_across_s'], 2)} over "
         f"{B['n_same_nu_pairs']} pairs. At these p, K* changes little between the tested s, so this contrast discriminates weakly.\n",
         "| p | s | K* | median K_2pct / median eff by nu | max cross-nu dK |", "|---|---|---|---|---|"]
    for c in B["cells"]:
        by = "; ".join(f"nu {k}: {v[0]} / {f(v[1])}" for k, v in c["by_nu_median_K2_eff"].items())
        L.append(f"| {c['p']} | {c['s']} | {c['K_star']} | {by} | {c['max_cross_nu_dK2']} |")
    return "\n".join(L) + "\n"


if __name__ == "__main__":
    write("E1", e1b())
    for exp in ("E6", "E7", "E8"):
        write(exp)
    print("wrote REPORT_A1.md for E1 E6 E7 E8")
